.version 7.2
.target sm_80
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 out_ptr,
    .param .u64 in_ptr,
    .param .u32 N
)
{
    // Registers
    .reg .pred   %p1;
    .reg .b32    %tid_x, %blk_dim_x, %grid_dim_x, %idx, %stride, %N;
    .reg .b64    %in_ptr, %out_ptr, %addr_in, %addr_out;
    .reg .b16    %h;
    .reg .f32    %f, %tanh_f;

    // Load kernel parameters
    ld.param.u64    %in_ptr,   [in_ptr];
    ld.param.u64    %out_ptr,  [out_ptr];
    ld.param.u32    %N,        [N];

    // Thread/block identifiers
    mov.u32         %tid_x,    %tid.x;
    mov.u32         %blk_dim_x,%ntid.x;
    mov.u32         %grid_dim_x,%ctaid.x;

    // Compute global linear index: idx = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.u32      %idx, %grid_dim_x, %blk_dim_x, %tid_x;

    // stride = gridDim.x * blockDim.x
    mul.lo.u32      %stride, %grid_dim_x, %blk_dim_x;

    // Loop over elements
    @! ( %idx < %N ) bra DONE;

LOOP:
    // Compute byte address = ptr + idx * sizeof(half) (2 bytes)
    mul.wide.u32    %addr_in, %idx, 2;
    add.u64         %addr_in, %in_ptr, %addr_in;

    // Load half
    ld.global.nc.f16 %h, [%addr_in];

    // Convert to float, compute tanh (approx), convert back
    cvt.f32.f16     %f, %h;
    tanh.approx.f32 %tanh_f, %f;
    cvt.f16.f32     %h, %tanh_f;

    // Store result
    mul.wide.u32    %addr_out, %idx, 2;
    add.u64         %addr_out, %out_ptr, %addr_out;
    st.global.f16   [%addr_out], %h;

    // idx += stride
    add.u32         %idx, %idx, %stride;
    setp.lt.u32     %p1, %idx, %N;
    @%p1 bra LOOP;

DONE:
    ret;
}
'''

class ModelNew:
    def __init__(self):
        # Load the PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """Apply element‑wise tanh on a half‑precision tensor using the PTX kernel."""
        assert x.is_cuda and x.dtype == torch.float16, "Input must be CUDA half tensor"
        out = torch.empty_like(x)

        N = x.numel()
        threads_per_block = 256
        blocks = ( (N + threads_per_block - 1) // threads_per_block, )

        # Launch the kernel
        ptx_launch(
            self.module,
            "tanh_kernel",
            grid=blocks,
            block=(threads_per_block,),
            args=[out.data_ptr(), x.data_ptr(), N]
        )
        return out
